#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	float _AlphaToMaskAvailable;
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
UNITY_BINDING(0) uniform UnityPerMaterial {
#endif
	UNITY_UNIFORM vec4                _BaseMap_ST;
	UNITY_UNIFORM vec4 Xhlslcc_UnusedX_DetailAlbedoMap_ST;
	UNITY_UNIFORM mediump vec4                _BaseColor;
	UNITY_UNIFORM mediump vec4 Xhlslcc_UnusedX_SpecColor;
	UNITY_UNIFORM mediump vec4 Xhlslcc_UnusedX_EmissionColor;
	UNITY_UNIFORM mediump float                _Cutoff;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_Smoothness;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_Metallic;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_BumpScale;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_Parallax;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_OcclusionStrength;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_ClearCoatMask;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_ClearCoatSmoothness;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_DetailAlbedoMapScale;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_DetailNormalMapScale;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_Surface;
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
};
#endif
layout(location = 0) out mediump vec4 SV_TARGET0;
float u_xlat0;
bool u_xlatb0;
mediump float u_xlat16_1;
float u_xlat2;
bool u_xlatb2;
bool u_xlatb4;
void main()
{
    u_xlat0 = _BaseColor.w + (-_Cutoff);
    u_xlat0 = u_xlat0 * 10000.0 + 0.5;
    u_xlat0 = clamp(u_xlat0, 0.0, 1.0);
    u_xlatb2 = 0.0>=_Cutoff;
    u_xlat0 = (u_xlatb2) ? 1.0 : u_xlat0;
    u_xlatb2 = _BaseColor.w>=_Cutoff;
    u_xlat2 = (u_xlatb2) ? _BaseColor.w : 0.0;
    u_xlatb4 = _AlphaToMaskAvailable!=0.0;
    u_xlat16_1 = (u_xlatb4) ? u_xlat0 : u_xlat2;
    u_xlat16_1 = u_xlat16_1 + -9.99999975e-05;
    u_xlatb0 = u_xlat16_1<0.0;
    if(u_xlatb0){discard;}
    SV_TARGET0 = vec4(0.0, 0.0, 0.0, 0.0);
    return;
}
